'use strict';
// Shared, pointer- and keyboard-accessible trim timeline for audio and video.
function trimBounds(duration,start,end,edge,value){
 const gap=Math.min(.05,duration);
 if(edge==='start')start=Math.max(0,Math.min(end-gap,value));
 else end=Math.min(duration,Math.max(start+gap,value));
 return {start,end};
}
class TrimTimeline {
 constructor(host,{change=()=>{},seek=()=>{},label='Clip',video=false}={}){
  this.host=host;this.video=video;this.change=change;this.seek=seek;this.duration=0;this.start=0;this.end=0;this.zoom=1;this.position=0;
  host.className='trim-editor';host.innerHTML=`<div class="trim-heading"><span>Drag the edges to trim</span><output class="trim-length">Choose a source</output></div><div class="trim-scroll"><div class="trim-track"><canvas class="trim-media" width="1200" height="80"></canvas><canvas class="trim-audio" width="1200" height="80" hidden></canvas><div class="trim-shade before"></div><div class="trim-shade after"></div><div class="trim-selection"></div><button type="button" class="trim-handle start" role="slider" aria-label="${label} start" aria-valuemin="0"><span>IN</span>❯</button><button type="button" class="trim-handle end" role="slider" aria-label="${label} end" aria-valuemin="0"><span>OUT</span>❮</button><div class="trim-playhead"></div></div></div><div class="trim-ruler"><output class="trim-start">0:00.0</output><span class="trim-wheel-hint">Scroll to zoom · drag to scrub</span><output class="trim-end">0:00.0</output></div>`;
  this.track=host.querySelector('.trim-track');this.canvas=host.querySelector('canvas');this.waveCanvas=host.querySelector('.trim-audio');this.scroll=host.querySelector('.trim-scroll');
  for(const edge of ['start','end']){const handle=host.querySelector('.trim-handle.'+edge);
   handle.onpointerdown=e=>{if(e.button!==0||!this.duration)return;e.preventDefault();e.stopPropagation();handle.setPointerCapture(e.pointerId);this.drag=edge;};
   handle.onpointermove=e=>{if(this.drag!==edge)return;this.setEdge(edge,this.timeAt(e));this.seek(this[edge]);};
   const finish=()=>{if(this.drag){this.seek(this.drag==='start'?this.start:this.end);this.drag=null;}};handle.onpointerup=finish;handle.onpointercancel=finish;handle.onlostpointercapture=finish;
   handle.onkeydown=e=>{if(!this.duration)return;let at=this[edge];if(e.key==='ArrowLeft')at-=e.shiftKey?1:.01;else if(e.key==='ArrowRight')at+=e.shiftKey?1:.01;else if(e.key==='Home')at=0;else if(e.key==='End')at=this.duration;else return;e.preventDefault();this.setEdge(edge,at);this.seek(this[edge]);};
  }
  this.track.onpointerdown=e=>{if(e.button!==0||e.target.closest('.trim-handle')||!this.duration)return;e.preventDefault();this.scrubbing=true;this.track.setPointerCapture(e.pointerId);this.seek(this.timeAt(e));};
  this.track.onpointermove=e=>{if(this.scrubbing)this.seek(this.timeAt(e));};
  this.track.onpointerup=this.track.onpointercancel=this.track.onlostpointercapture=()=>{this.scrubbing=false;};
  this.scroll.addEventListener('wheel',e=>{if(!this.duration||!e.deltaY)return;e.preventDefault();this.zoomAt(e.clientX,this.zoom*Math.exp(-Math.max(-300,Math.min(300,e.deltaY))*.003));},{passive:false});this.render();
 }
 zoomAt(clientX,zoom){const rect=this.scroll.getBoundingClientRect(),x=Math.max(0,Math.min(rect.width,clientX-rect.left)),trackRect=this.track.getBoundingClientRect(),fraction=(clientX-trackRect.left)/trackRect.width;this.zoom=Math.max(1,Math.min(256,zoom));this.track.style.width=this.zoom*100+'%';this.scroll.scrollLeft=Math.max(0,fraction*this.track.getBoundingClientRect().width-x);this.drawWave();}
 timeAt(e){const r=this.track.getBoundingClientRect();return Math.max(0,Math.min(this.duration,(e.clientX-r.left)/r.width*this.duration));}
 setEdge(edge,value){Object.assign(this,trimBounds(this.duration,this.start,this.end,edge,value));this.render();this.change(this.start,this.end);}
 set(duration,start=0,end=Math.min(duration,10)){this.duration=duration;this.start=start;this.end=end;this.zoom=Math.max(1,Math.min(16,Math.ceil(duration/Math.max(.05,end-start)/3)));this.track.style.width=this.zoom*100+'%';this.host.querySelector('.trim-scroll').scrollLeft=0;this.buffer=null;this.peaks=null;for(const canvas of [this.canvas,this.waveCanvas])canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);this.playhead(start);this.render();}
 render(){const percent=t=>this.duration?t/this.duration*100:0,left=percent(this.start),right=percent(this.end);for(const edge of ['start','end']){const h=this.host.querySelector('.trim-handle.'+edge);h.style.left=percent(this[edge])+'%';h.disabled=!this.duration;h.setAttribute('aria-valuenow',this[edge].toFixed(2));h.setAttribute('aria-valuemax',this.duration);h.setAttribute('aria-valuetext',samplerSeconds(this[edge]));}
  const select=this.host.querySelector('.trim-selection');select.style.left=left+'%';select.style.width=(right-left)+'%';this.host.querySelector('.before').style.width=left+'%';this.host.querySelector('.after').style.left=right+'%';this.host.querySelector('.after').style.width=(100-right)+'%';
  this.host.querySelector('.trim-start').textContent=samplerSeconds(this.start);this.host.querySelector('.trim-end').textContent=samplerSeconds(this.end);this.host.querySelector('.trim-length').textContent=this.duration?samplerSeconds(this.end-this.start)+' selected'+(this.end-this.start>120?' · max 2 minutes':''):'Choose a source';this.host.classList.toggle('trim-too-long',this.end-this.start>120);
 }
 playhead(time,follow=false){this.position=time;this.host.querySelector('.trim-playhead').style.left=(this.duration?time/this.duration*100:0)+'%';if(follow&&this.duration&&this.scroll.clientWidth){const x=time/this.duration*this.track.getBoundingClientRect().width;if(x<this.scroll.scrollLeft||x>this.scroll.scrollLeft+this.scroll.clientWidth-30)this.scroll.scrollLeft=Math.max(0,x-this.scroll.clientWidth*.3);}}
 waveform(buffer){this.buffer=buffer;const data=buffer.getChannelData(0),count=Math.min(131072,data.length);this.peaks=new Float32Array(count);for(let i=0;i<count;i++){let peak=0;for(let at=Math.floor(i*data.length/count);at<Math.floor((i+1)*data.length/count);at++)peak=Math.max(peak,Math.abs(data[at]));this.peaks[i]=peak;}this.drawWave();}
 showAudio(show){this.waveCanvas.hidden=!show;this.track.classList.toggle('has-audio',show);this.drawWave();}
 drawWave(){if(!this.peaks||(this.video&&this.waveCanvas.hidden))return;const canvas=this.video?this.waveCanvas:this.canvas,ctx=canvas.getContext('2d'),data=this.peaks;canvas.width=Math.min(16000,Math.max(1200,Math.round(this.track.getBoundingClientRect().width)));const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#91c77c';for(let x=0;x<w;x++){const from=Math.floor(x*data.length/w),to=Math.max(from+1,Math.floor((x+1)*data.length/w));let peak=0;for(let i=from;i<to;i++)peak=Math.max(peak,Math.abs(data[i]||0));const height=Math.max(2,peak*h*.9);ctx.fillRect(x,(h-height)/2,1,height);}}
}
let videoTrim=null,audioTrim=null,audioTrimBuffer=null,audioTrimBoard='',audioTrimLoad=0,audioTrimPreviewRange=null;
function initTrimEditors(){
 videoTrim=new TrimTimeline($('videoTrim'),{label:'Video trim',video:true,change:(start,end)=>{$('samplerIn').value=start.toFixed(2);$('samplerOut').value=end.toFixed(2);},seek:time=>{$('samplerEditorVideo').pause();$('samplerEditorVideo').currentTime=time;}});
 for(const [id,edge]of [['samplerIn','start'],['samplerOut','end']])$(id).onchange=()=>videoTrim.setEdge(edge,Number($(id).value));
 $('samplerSetIn').onclick=()=>videoTrim.setEdge('start',$('samplerEditorVideo').currentTime);$('samplerSetOut').onclick=()=>videoTrim.setEdge('end',$('samplerEditorVideo').currentTime);
 audioTrim=new TrimTimeline($('audioTrim'),{label:'Audio trim',change:()=>{stopAudioTrimPreview();},seek:time=>{audioTrim.playhead(time);}});
 $('openAudioTrim').onclick=()=>openAudioTrimmer();$('closeAudioTrim').onclick=closeAudioTrimmer;
 $('audioTrimDialog').addEventListener('cancel',()=>{audioTrimLoad++;audioTrimPreviewRange=null;nativeStopSound('@audio-preview').catch(()=>{});});
 $('audioTrimFile').onchange=async()=>{const file=$('audioTrimFile').files[0];if(!file)return;try{if(file.size>200*1024*1024)throw new Error('Choose audio or video up to 200 MB.');await loadAudioTrim(await file.arrayBuffer(),file.name.replace(/\.[^.]+$/,''));}catch(e){$('audioTrimStatus').textContent=errorText(e);}};
 $('audioTrimPreview').onclick=async()=>{try{if(!audioTrimBuffer)return;if(audioTrim.end-audioTrim.start>120)throw new Error('Trim the preview to 2 minutes or less.');if(!active&&!await start())return;await sendTrimPreview(samplerWAV(audioTrimBuffer,audioTrim.start,audioTrim.end),audioTrimBoard);audioTrimPreviewRange={start:audioTrim.start,end:audioTrim.end,seen:false};audioTrim.playhead(audioTrim.start);$('audioTrimStatus').textContent='Playing your selection through the selected outputs.';}catch(e){$('audioTrimStatus').textContent=errorText(e);}};
 $('audioTrimStop').onclick=()=>stopAudioTrimPreview();
 $('audioTrimSave').onclick=async()=>{try{if(!audioTrimBuffer)return;if(audioTrim.end-audioTrim.start>120)throw new Error('Trim your sound bite to 2 minutes or less.');await withLoading('Saving sound bite…',async()=>{const name=$('audioTrimName').value.trim();if(!name)throw new Error('Name your sound bite.');const response=await fetch(new URL('sampler/bite',location.href),{method:'POST',headers:{'Content-Type':'audio/wav','X-Bite-Board':audioTrimBoard,'X-Bite-Name':btoa(String.fromCharCode(...new TextEncoder().encode(name)))},body:samplerWAV(audioTrimBuffer,audioTrim.start,audioTrim.end)});if(!response.ok)throw new Error(await response.text());library=await response.json();renderLibrary(audioTrimBoard);closeAudioTrimmer();$('boardStatus').textContent='Sound bite added. The source audio is unchanged.';},true);}catch(e){$('audioTrimStatus').textContent=errorText(e);}};
}
async function sendTrimPreview(wav,board){await nativeStopSound('@audio-preview');const response=await fetch(new URL('sampler/preview',location.href),{method:'POST',headers:{'Content-Type':'audio/wav','X-Sampler-Board':board,'X-Preview-ID':'@audio-preview'},body:wav});if(!response.ok)throw new Error(await response.text());}
async function openAudioTrimmer(sound){const generation=++audioTrimLoad;audioTrimPreviewRange=null;audioTrimBoard=$('boardSelect').value;audioTrimBuffer=null;audioTrim.set(0);$('audioTrimName').value='';$('audioTrimFile').value='';$('audioTrimSave').disabled=$('audioTrimPreview').disabled=true;$('audioTrimStatus').textContent='Choose audio or video, then drag IN and OUT to extract a sound bite. The source stays unchanged.';$('audioTrimDialog').showModal();if(sound)try{const response=await fetch(samplerURL('clip',sound.ID));if(!response.ok)throw new Error('Could not open this clip.');const bytes=await response.arrayBuffer();if(generation!==audioTrimLoad)return;await loadAudioTrim(bytes,sound.Name);}catch(e){$('audioTrimStatus').textContent=errorText(e);}}
async function loadAudioTrim(bytes,name){const generation=++audioTrimLoad;audioTrimPreviewRange=null;audioTrimBuffer=null;$('audioTrimStatus').textContent='Loading audio and drawing waveform…';$('audioTrimSave').disabled=$('audioTrimPreview').disabled=true;await nativeStopSound('@audio-preview');await withLoading('Drawing audio waveform…',async()=>{const context=new OfflineAudioContext(1,1,48000);let buffer;try{buffer=await context.decodeAudioData(bytes);}catch(e){throw new Error('Could not read the audio track. Try WAV, MP3, MP4 with AAC, or WebM with Opus.');}if(generation!==audioTrimLoad)return;if(!buffer.duration||buffer.duration>1800)throw new Error('Choose audio up to 30 minutes long.');audioTrimBuffer=buffer;audioTrim.set(buffer.duration,0,Math.min(buffer.duration,10));audioTrim.waveform(buffer);$('audioTrimName').value=(name+' bite').slice(0,80);$('audioTrimSave').disabled=$('audioTrimPreview').disabled=false;$('audioTrimStatus').textContent=samplerSeconds(buffer.duration)+' source · drag either edge, or zoom in for a precise cut.';},true);}
function closeAudioTrimmer(){audioTrimLoad++;audioTrimPreviewRange=null;nativeStopSound('@audio-preview').catch(()=>{});audioTrimBuffer=null;audioTrim.buffer=null;$('audioTrimDialog').close();}
async function drawVideoTrimFrames(source){if(!videoTrim)return;const id=source.ID,video=document.createElement('video');video.muted=true;video.preload='auto';const ctx=videoTrim.canvas.getContext('2d');ctx.clearRect(0,0,1200,80);try{const loaded=waitVideo(video,'loadeddata');video.src=samplerURL('source',id);video.load();await loaded;for(let i=0;i<12;i++){if(samplerSource?.ID!==id)return;await seekSamplerVideo(video,Math.min(samplerDuration-.01,(i+.5)/12*samplerDuration));if(samplerSource?.ID!==id)return;ctx.drawImage(video,0,0,video.videoWidth,video.videoHeight,i*100,0,100,80);}}catch(e){/* Source remains editable even when thumbnails are unavailable. */}finally{video.removeAttribute('src');video.load();}}
function stopAudioTrimPreview(){audioTrimPreviewRange=null;nativeStopSound('@audio-preview').catch(()=>{});}
function updateTrimPlayback(items){if(!audioTrimPreviewRange||!audioTrim)return;const r=audioTrimPreviewRange,item=items.filter(i=>i.ID==='@audio-preview').sort((a,b)=>b.Sequence-a.Sequence)[0];if(item){r.seen=true;audioTrim.playhead(Math.min(r.end,r.start+item.Position),true);}else if(r.seen){audioTrim.playhead(r.end);audioTrimPreviewRange=null;}}
$('samplerWaveform').onchange=()=>{videoTrim.showAudio($('samplerWaveform').checked);if($('samplerWaveform').checked&&samplerSource)loadVideoWaveform(samplerSource);};
async function loadVideoWaveform(source){$('samplerWaveStatus').textContent='Loading audio waveform…';try{if(samplerDuration>600)throw new Error('Audio waveform supports videos up to 10 minutes.');const buffer=await decodeSamplerAudio(source);if(samplerSource?.ID!==source.ID)return;videoTrim.waveform(buffer);$('samplerWaveStatus').textContent='Audio waveform · align IN with the first sound.';}catch(e){if(samplerSource?.ID===source.ID)$('samplerWaveStatus').textContent=errorText(e);}}
$('samplerPatch').onclick=()=>{const board=$('samplerBoard').value;openTab('patch');if(!patchGraph.Nodes.some(n=>n.Kind==='board'&&n.BoardID===board))addPatchNode(patchNode('board',{BoardID:board},40,180+patchGraph.Nodes.length*20));else renderPatch();patchStatus('Connect this video sampler to an effect or output, and enable Patch bay.');};
$('samplerCropDetails').ontoggle=()=>{$('samplerCropBox').hidden=!$('samplerCropDetails').open;};
initTrimEditors();
